 void saveBody(String revision){String prior=store.origin.revision().toString();store.current=revision;store.head=store.head.add(BigInteger.ONE);store.issue=store.issue.add(BigInteger.ONE);
  store.transitions.add(json.object().put("document_id",DOC).put("transition_id",UUID.randomUUID().toString()).put("kind","INVALIDATE").put("previous_revision",prior).put("revision",PermissionSchema.next(prior)).put("previous_status",store.origin.status()).put("status","REANCHOR_REQUIRED").put("previous_anchor_id",store.pointer.anchorId()).put("anchor_id",store.pointer.anchorId()).put("document_revision",revision).put("actor_id",ACTOR).put("reason","DOCUMENT_REVISION_SAVED"));store.origin=row(store.origin,"REANCHOR_REQUIRED",store.origin.revision().add(BigInteger.ONE),store.origin.replyCount());}
 com.fasterxml.jackson.databind.node.ObjectNode requestForCurrent()throws Exception{var r=input().put("document_revision",store.current).put("expected_revision",store.origin.revision().toString()).put("expected_document_revision",store.head.toString()).put("expected_anchor_id",store.pointer.anchorId()).put("expected_anchor_revision",store.pointer.revision().toString());r.set("selection",json.tree(selection(store.current)));return r;}



 com.fasterxml.jackson.databind.node.ObjectNode reconcileInput(){var n=input().put("expected_revision",store.origin.revision().toString()).put("expected_document_revision",store.head.toString());n.remove("selection");return n;}
 JsonNode reconcile()throws Exception{return reconcile(reconcileInput());}
 JsonNode reconcile(JsonNode n)throws Exception{return reconciliation.reconcile(subject,"1",KEY+"-reconcile",ANNOTATION,json.canonical(n).getBytes(StandardCharsets.UTF_8));}
