 static AnnotationThreadProtocol.Row row(AnnotationThreadProtocol.Row r,String status,BigInteger revision,BigInteger replies){return new AnnotationThreadProtocol.Row(r.tenantId(),r.projectId(),r.annotationId(),r.documentRevision(),r.nodeId(),r.selectionJson(),r.selectionArtifactId(),r.selectionSha256(),status,r.content(),r.actorId(),r.schemaVersion(),r.schemaManifest(),r.createdBy(),r.createdAt(),r.classification(),revision,r.updatedAt(),replies);}
 void assertClean(){assertEquals("REANCHOR_REQUIRED",store.origin.status());assertEquals(BigInteger.TWO,store.origin.revision());assertEquals(1,store.anchors.size());assertEquals(1,store.transitions.size());assertEquals(ANNOTATION,store.pointer.anchorId());assertEquals(BigInteger.ONE,store.head);assertEquals(BigInteger.ONE,store.issue);assertTrue(store.artifacts.isEmpty());assertNull(store.audit);assertTrue(store.events.isEmpty());}
